#include "glue.h"
const QcaNativeScan*qca_scan_native_view(void);
static int apart(const void*a,unsigned n,const void*b,unsigned m){return a&&b&&(uintptr_t)a<=UINTPTR_MAX-n&&(uintptr_t)b<=UINTPTR_MAX-m&&((uintptr_t)a+n<=(uintptr_t)b||(uintptr_t)b+m<=(uintptr_t)a);}
static int healthy(QsgNative*s,uint64_t now){return s&&s->data&&s->station&&!s->fault&&s->epoch&&now>=s->last&&s->epoch==s->data->epoch&&s->epoch==s->station->epoch&&!s->station->quarantined&&s->data->phase==QDP_RX_ACTIVE&&s->data->aggr_done&&!s->data->error&&s->data->radio&&s->data->radio->htt_owner==s->data&&s->data->radio->epoch==s->epoch&&s->data->runtime&&s->data->runtime->epoch==s->epoch;}
void qsg_revoke(QsgNative*s,unsigned reason){if(!s)return;if(!s->fault)s->fault=reason?reason:1;if(s->station&&s->station->epoch==s->epoch){s->station->quarantined=1;s->station->core_completed=0;}if(s->data)qdp_quarantine(s->data,s->fault);}
int qsg_begin(QsgNative*s,QcaHttDataPath*d,StaJoin*station,const StaWireBss*b,uint16_t selected,uint16_t listen,const uint8_t source[32],uint64_t now){if(!s||s->epoch||!d||!station||!b||!source||!apart(s,sizeof(*s),d,sizeof(*d))||!apart(s,sizeof(*s),station,sizeof(*station))||!apart(s,sizeof(*s),b,sizeof(*b))||!apart(s,sizeof(*s),source,32)||d->phase!=QDP_RX_ACTIVE||!d->aggr_done||d->error||d->tx_posted||!d->radio||!d->runtime||d->radio->htt_owner!=d||d->radio->epoch!=d->epoch||d->runtime->epoch!=d->epoch||station->epoch!=d->epoch||!station->mapped||station->peer_id>=2048||station->pending||station->ptk||station->gtk||station->watermark>d->radio->rx.completed||station->htt_endpoint!=d->binding.endpoint)return 0;const QcaNativeScan*capture=qca_scan_native_view();if(!capture||capture->radio!=d->radio||capture->epoch!=d->epoch||capture->phase!=QCA_NATIVE_SCAN_LIVE_DONE||capture->error||capture->quiesce_requested)return 0;QsgNative n={0};n.data=d;n.station=station;n.epoch=d->epoch;n.last=now;if(d->tx_id>=65533)return 0;n.next_id=(uint16_t)(d->tx_id+1);if(!stx_begin(&n.mgmt,b,station,now,selected,listen,STX_BACKEND_HTT_MGMT3,source))return 0;*s=n;return 1;}
static int joined(QsgNative*s,uint64_t now){QcaHttDataPath*d=s->data;StaMgmtTx*m=&s->mgmt;if(!m->posted)return 1;if(d->tx_id!=m->msdu_id||d->tx_cookie!=m->cookie){qsg_revoke(s,20);return 0;}if(d->tx_dma_done&&!m->dma_closed&&!stx_dma_closed(m,d->tx_cookie,now)){qsg_revoke(s,21);return 0;}if(d->tx_htt_done&&!m->status_seen&&!stx_status(m,s->epoch,(uint16_t)d->tx_id,(uint32_t)d->tx_rx_completion,d->tx_status,now)){qsg_revoke(s,22);return 0;}if(m->phase==STX_FAULT){qsg_revoke(s,23);return 0;}return 1;}
int qsg_poll(QsgNative*s,uint64_t now){if(!healthy(s,now)){qsg_revoke(s,2);return -1;}s->last=now;if(qdp_poll_dma(s->data,now)<0||!joined(s,now)){qsg_revoke(s,3);return -1;}int rc=stx_poll(&s->mgmt,now);if(rc<0){qsg_revoke(s,4);return -1;}if(rc==1)return 1;if(s->mgmt.posted)return 0;uint8_t frame[128];unsigned n=stx_prepare(&s->mgmt,frame,sizeof frame,s->sequence);if(!n||s->next_id>=65535){qsg_revoke(s,5);return -1;}if(!qdp_submit_mgmt(s->data,frame,n,s->next_id,s->station->vdev,now)){qsg_revoke(s,6);return -1;}if(s->data->tx_floor>UINT32_MAX||!stx_posted(&s->mgmt,s->data->tx_cookie,s->next_id,(uint32_t)s->data->tx_floor,now)){qsg_revoke(s,7);return -1;}s->next_id++;s->sequence=(s->sequence+1)&4095;return 0;}
int qsg_receive(QsgNative*s,const QcaRxEvent*e,uint64_t now){if(!healthy(s,now)||!e||!apart(s,sizeof(*s),e,sizeof(*e))||e->completion>s->data->radio->rx.completed){qsg_revoke(s,8);return -1;}s->last=now;QcaHtcFrame credit={0};if(e->raw_bytes<=2048&&qca_htc_decode(e->raw,e->raw_bytes,&credit)&&credit.endpoint==e->endpoint&&credit.payload_bytes==e->bytes&&!credit.payload_bytes){if(s->diagnostic_count==8){qsg_revoke(s,14);return -1;}s->diagnostic[s->diagnostic_count++]=*e;return 1;}
 if(e->pipe==2){StaEvent event={0};int decoded=sta_decode_mgmt(e,s->station->wmi_endpoint,s->mgmt.bss.frequency,s->mgmt.bss.peer,s->mgmt.bss.own,s->mgmt.bss.native_rates,&event);if(decoded==1&&event.kind==STA_DEAUTH&&event.completion>s->station->watermark){(void)sta_observe(s->station,s->epoch,&event);qsg_revoke(s,13);return -1;}int accepted=stx_response(&s->mgmt,s->epoch,e,s->mgmt.bss.frequency,s->mgmt.bss.native_rates,now);if(accepted)s->responses[s->mgmt.step?1:0]=*e;return s->mgmt.phase==STX_FAULT?(qsg_revoke(s,9),-1):(accepted?1:0);}
 QcaHtcFrame f;if(e->pipe!=1||e->endpoint!=s->data->binding.endpoint||e->event||!qca_htc_decode(e->raw,e->raw_bytes,&f)||f.endpoint!=e->endpoint||f.payload_bytes!=e->bytes){qsg_revoke(s,10);return -1;}
 if(f.payload_bytes&&(f.payload[0]==3||f.payload[0]==4||f.payload[0]==11)){QcaHttVersion version={0};version.major=3;version.minor=56;int rc=sta_observe_owned(s->station,s->epoch,e,s->mgmt.bss.frequency,s->mgmt.bss.native_rates,&s->data->binding,&version);if(s->station->quarantined){qsg_revoke(s,11);return -1;}return rc;}
 int rc=qdp_receive(s->data,e,now);if(rc<0||!joined(s,now)){qsg_revoke(s,12);return -1;}return rc;
}
